web/src/styles/r426.css:
/* Migrated from user-supplied R4.2.6 EDITABLE-CSS. */
:root {
  --hp-run-complete-size: 16px;
}
/* R4.2 · Paper Flame x Mercury x EXP-02 A/B/C — visual layer ONLY.
   The production React bundle, fixture, source reference and behavioral controls remain unchanged. */
:root {
  --r42-ink: #202a34;
  --r42-muted: #5d6f7b;
  --r42-border: #d6dfe7;
  --r42-ice: #f5f8fb;
  --r42-white: #fff;
  --r42-silver: #a5b7c4;
  --r42-ember: #eb6044;
  --r42-ember-dark: #b94025;
  --r42-signal: #2879bf;
  --r42-ease: cubic-bezier(0.22, 0.8, 0.2, 1);
}
/* Four-zone spatial hierarchy: only the global rail owns a dark slab. */
.hp-shell {
  background: #f5f7f9;
}
.hp-shell .hp-rail {
  background: #16212c;
  box-shadow: inset -1px 0 0 #283946;
  gap: 21px;
}
.hp-rail .hp-brand-symbol {
  color: #ee7a60;
  border-color: #354757;
  background: #1b2a37;
}
.hp-rail .hp-brand-wordmark {
  letter-spacing: -0.035em;
}
.hp-rail nav {
  gap: 8px;
}
.hp-rail nav button {
  border-radius: 15px;
  min-height: 66px;
  transition:
    background 0.22s var(--r42-ease),
    color 0.22s ease,
    transform 0.22s var(--r42-ease);
}
.hp-rail nav button svg {
  width: 23px;
  height: 23px;
  stroke-width: 1.7;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.hp-rail nav button[aria-current="page"] {
  background: #34414a;
  color: #fff0e9;
}
.hp-rail nav button:hover:not([aria-current="page"]) {
  background: #263743;
  color: #f4f7fa;
  transform: translateY(-1px);
}
.hp-rail .hp-rail-track {
  background: #eb6044;
  border-radius: 5px;
  box-shadow: 0 0 8px #eb604439;
}
.hp-shell .hp-sidebar {
  background: linear-gradient(112deg, #edf1f5 0%, #f3f6f9 100%);
  border-right: 1px solid #d8e1e9;
}
.hp-sidebar-eyebrow {
  color: #ac5845;
  letter-spacing: 0.14em;
  font-size: 10px;
}
.hp-shell .hp-sidebar__header {
  padding-bottom: 10px;
}
.hp-conversation-search {
  background: #fff;
  border: 1px solid #d5dfe7;
  border-radius: 13px;
  box-shadow: 0 2px 8px #20344605;
}
.hp-conversation-search:focus-within {
  border-color: #9bacba;
  box-shadow: 0 0 0 3px #b4c8d22b;
}
.hp-shell .hp-conv {
  border-radius: 15px;
  border: 1px solid transparent;
  transition:
    background 0.22s var(--r42-ease),
    border-color 0.22s var(--r42-ease),
    box-shadow 0.22s var(--r42-ease),
    transform 0.22s var(--r42-ease);
}
.hp-shell .hp-conv:hover:not(.hp-conv--active) {
  background: #ffffffa8;
  transform: translateX(1px);
}
.hp-shell .hp-conv--active {
  background: #fff;
  border-color: #cbd9e4;
  box-shadow:
    0 8px 22px #1c35480b,
    inset 0 1px 0 #fff;
}
.hp-conv--active::before {
  width: 2px !important;
  background: #d26950 !important;
  border-radius: 8px;
  opacity: 0.85;
}
.hp-conv-icon {
  stroke-width: 1.7 !important;
}
.hp-conv--active .hp-conv-icon {
  color: #ad513a;
  background: #fcebe6;
  border-color: #f4c7b9;
}
/* Text-first main canvas; the message DOM remains ordinary selectable text. */
.hp-shell .hp-conversation-header {
  border-bottom: 1px solid #dce4eb;
  background: #fbfcfe;
}
.hp-title-trigger {
  font-weight: 680;
  letter-spacing: -0.025em;
  color: #233445;
}
.hp-thread__viewport {
  scrollbar-color: #b5c7d3 transparent;
}
.hp-msg[data-role="assistant"] .hp-text-part {
  line-height: 1.78;
  letter-spacing: 0.006em;
}
.hp-msg[data-role="assistant"] .hp-answer-surface::after {
  border-color: #b5c6d1;
}
.hp-artifact-message-open {
  color: #a9422a !important;
  border-color: #e7b5a5 !important;
  background: #fffaf8 !important;
  border-radius: 10px !important;
}
.hp-artifact-message-open:hover {
  background: #fff0e8 !important;
}
/* R4.2 Run-card optical hierarchy: icon/identity -> status -> provenance. */
.hp-execution-block:not(:has(.hp-runstrip)) > .hp-run-detail {
  grid-template-columns: minmax(0, 1fr) auto 34px;
  gap: 9px 15px;
  min-height: 118px;
  padding: 16px 17px !important;
  border-radius: 16px !important;
  border: 1px solid #d7e1e9 !important;
  background: linear-gradient(170deg, #fff 0%, #fbfcfe 100%) !important;
  box-shadow:
    0 7px 22px #19304609,
    inset 0 1px 0 #fff;
  transition:
    border-color 0.22s var(--r42-ease),
    box-shadow 0.22s var(--r42-ease),
    transform 0.22s var(--r42-ease);
}
.hp-execution-block:not(:has(.hp-runstrip)) > .hp-run-detail:hover {
  border-color: #b7c9d5 !important;
  box-shadow: 0 11px 28px #19304614;
  transform: translateY(-1px);
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-kind {
  font-size: 10px;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: #91a2b1;
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-copy {
  gap: 3px;
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-copy > span:first-child {
  font-weight: 700;
  font-size: 15px;
  letter-spacing: -0.01em;
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-copy > .hp-run-reference-caption {
  font-size: 11px;
  color: #708290;
}
.hp-run-reference-id {
  font:
    11px/1.5 ui-monospace,
    Consolas,
    monospace;
  letter-spacing: 0.01em;
  color: #8494a4 !important;
}
.hp-run-card-status {
  grid-column: 2 !important;
  grid-row: 1 / span 2 !important;
  width: auto;
  min-width: 100px;
  justify-self: end;
  padding: 5px 9px;
  border: 1px solid #dce7eb;
  border-radius: 999px;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 650;
  gap: 7px;
  background: #f2f7fa;
  color: #61788b;
}
.hp-run-card-status[data-status="succeeded"] {
  background: #edf7f2;
  border-color: #cae6d7;
  color: #207454;
}
.hp-run-card-status[data-status="failed"] {
  background: #fff0ef;
  border-color: #f1d2cf;
  color: #b94043;
}
.hp-run-card-status[data-status="running"] {
  background: #eaf3ff;
  border-color: #c4def2;
  color: #2879bf;
}
.hp-run-card-status[data-status="queued"] {
  background: #fff4e2;
  border-color: #f0d9b4;
  color: #95611c;
}
.hp-run-card-status[data-status="cancelling"] {
  background: #eef2f4;
  border-color: #d8dfe4;
  color: #657985;
}
.hp-run-card-dot {
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  background: transparent !important;
  box-shadow: none !important;
  border: 1px solid currentColor;
  display: grid;
  place-items: center;
  opacity: 0.95;
}
.hp-run-card-dot svg {
  width: 17px;
  height: 17px;
  stroke-width: 1.9;
  fill: none;
  stroke: currentColor;
}
.hp-run-card-status[data-status="running"] .hp-run-card-dot {
  animation: r42-orbit 2.6s linear infinite;
}
.hp-run-card-status[data-status="succeeded"] > span:last-child {
  font-family:
    system-ui,
    -apple-system,
    sans-serif !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  letter-spacing: 0 !important;
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-detail > svg {
  grid-column: 3 !important;
  grid-row: 1 / span 2 !important;
  align-self: center;
  width: 28px;
  height: 28px;
  padding: 5px;
  border-radius: 9px;
  color: #687f90;
  background: #eef3f7;
  border: 1px solid #dce5eb;
}
.hp-execution-block:not(:has(.hp-runstrip)) .hp-run-card-meta {
  grid-column: 1 / span 3;
  grid-row: 3;
  padding-top: 10px;
  margin-top: 3px;
  border-top: 1px solid #e9eef3;
  gap: 7px 14px;
  font-size: 11px;
  color: #708393;
}
@keyframes r42-orbit {
  to {
    transform: rotate(360deg);
  }
}
/* Agent Vitality: same semantic palette in compact and detail; no giant success medal. */
.hp-vitality-heading--detail {
  display: flex !important;
  align-items: center;
  gap: 14px;
  min-height: 70px;
}
.hp-vitality-heading--detail > span:first-child {
  flex: none;
}
.hp-vitality--detail .hp-vitality__frame {
  width: 62px !important;
  height: 62px !important;
  border-radius: 19px !important;
  border-width: 1px !important;
  box-shadow: inset 0 1px 0 #ffffffad;
}
.hp-vitality--detail .hp-vitality__layer svg {
  width: 46px !important;
  height: 46px !important;
}
.hp-vitality--detail .hp-vitality__layer svg circle:first-child {
  opacity: 0.12;
}
.hp-vitality-copy {
  min-width: 0;
}
.hp-vitality-label {
  font-size: 17px !important;
  font-weight: 750 !important;
  letter-spacing: -0.015em;
}
.hp-vitality-caption {
  font-size: 12px !important;
  color: #687d8c !important;
}
.hp-vitality-facts {
  border: 1px solid #e2ebf1;
  border-radius: 12px;
  background: #f8fafc;
  padding: 12px !important;
  gap: 9px !important;
}
.hp-vitality-facts > div {
  min-width: 0;
}
.hp-vitality-facts dt {
  font-size: 11px;
  color: #7a8b99;
}
.hp-vitality-facts dd {
  font-size: 12px;
  font-weight: 600;
  color: #2b4052;
}
.hp-run-inspector .hp-inspector-card {
  background: #fff !important;
  border-color: #dce6ed !important;
  border-radius: 16px !important;
  padding: 17px !important;
  gap: 13px !important;
  box-shadow: 0 8px 24px #20374e07;
}
.hp-run-inspector .hp-inspector-card > h3 {
  font-size: 17px !important;
  line-height: 1.4;
  letter-spacing: -0.018em;
  color: #2c4455;
}
.hp-run-result {
  color: #354b5d;
  line-height: 1.7;
}
.hp-run-inspector .hp-run-timestamps {
  border-top: 1px solid #e5ecf2;
}
.hp-run-inspector .hp-run-origin-action {
  color: #386e93;
  background: #f0f6fb !important;
  border: 1px solid #d6e5ee !important;
  border-radius: 10px;
}
/* Inspector as connected porcelain tool-surface, preserving arrival/close state machine. */
.hp-shell .hp-inspector {
  background: linear-gradient(105deg, #f1f4f7, #f7f9fb);
  border-left: 1px solid #c6d4de;
  box-shadow: inset 5px 0 12px #bbccd40b;
}
.hp-inspector .hp-surface-header {
  border-bottom: 1px solid #d8e4ea;
  background: linear-gradient(180deg, #fafbfc, #f2f6f8);
  padding: 13px 16px;
}
.hp-inspector .hp-surface-header h2 {
  letter-spacing: -0.01em;
  color: #243749;
}
.hp-run-identity .hp-object-kind {
  font-size: 12px !important;
  letter-spacing: 0.12em !important;
  text-transform: uppercase;
  color: #677e8f !important;
}
.hp-inspector-tabs {
  border-bottom: 1px solid #dce6ec;
  padding-bottom: 2px;
}
.hp-inspector-tabs button {
  border-radius: 9px 9px 0 0 !important;
  font-size: 12px !important;
  color: #6f8493;
}
.hp-inspector-tabs button[aria-selected="true"] {
  color: #a94a33;
  font-weight: 700;
  background: #fceee8a6 !important;
}
.hp-inspector-tab-indicator {
  height: 2px;
  background: #eb6044;
  border-radius: 3px;
}
.hp-inspector :is(button, [role="tab"]):focus-visible,
.hp-shell button:focus-visible {
  outline: 2px solid #b94025;
  outline-offset: 2px;
}
.hp-inspector .hp-run-sync {
  color: #507389 !important;
}
.hp-inspector-presentation[data-inspector-phase="receiving"] [data-inspector-gate] {
  visibility: hidden;
}
.hp-inspector-accept {
  border-color: #afc0cb;
}
.hp-filament-shell {
  stroke: #c5d2da;
  stroke-opacity: 0.33;
}
.hp-filament-echo {
  stroke: #f0f6f9;
  stroke-opacity: 0.78;
}
/* Surface is promoted only when opened; never brighten every panel. */
.hp-surface[open],
dialog.hp-surface[open] {
  box-shadow:
    0 22px 68px #142e4026,
    0 1px 0 #fff inset;
  border: 1px solid #cbdce5;
}
/* Composer: quiet cold porcelain + single local ember, no double hotspots. */
.hp-shell .hp-composer {
  border-radius: 19px !important;
  background: linear-gradient(160deg, #fff 0%, #fcfdff 100%);
  border: 1px solid #d3dfe7;
  box-shadow:
    0 12px 32px #1935470f,
    0 2px 7px #19354707;
  position: relative;
  isolation: isolate;
  overflow: visible;
  transition:
    border-color 0.22s var(--r42-ease),
    box-shadow 0.22s var(--r42-ease);
}
.hp-shell .hp-composer:focus-within {
  border-color: #a6bdcc;
  box-shadow:
    0 14px 33px #19354711,
    0 0 0 2px #b3c6d226;
}
.hp-shell .hp-composer:before {
  height: 1px;
  background: linear-gradient(90deg, transparent, #b6c8d3 40%, #edf3f7 60%, transparent);
}
.hp-shell .hp-composer:after {
  width: min(37%, 240px);
  right: 66px;
  height: 2px;
  bottom: 4px;
  background: linear-gradient(90deg, transparent, #e8a68e 17%, #eb6044 66%, transparent);
}
.hp-shell .hp-composer[data-action-phase="ready"]:after {
  opacity: 0.87;
}
.hp-shell .hp-composer[data-action-phase="intent"]:after {
  opacity: 0.12;
}
.hp-composer__input {
  color: #273c4d;
}
.hp-composer__input::placeholder {
  color: #8094a3;
}
.hp-shell .hp-composer button.hp-resource-use {
  color: #5f7485;
  min-height: 36px;
}
.hp-shell .hp-composer button.hp-resource-use:hover {
  color: #b04f38;
  background: #fdf2ed;
}
.hp-mode-select {
  color: #4d6577;
  font-weight: 600;
  cursor: pointer;
}
.hp-composer__submit {
  gap: 8px;
}
.hp-shell .hp-composer button.hp-composer__send:not(:disabled) {
  background: #b94025;
  border-color: #b94025;
  color: #fff;
  box-shadow: 0 3px 10px #bb533132;
}
.hp-shell .hp-composer[data-action-phase="ready"] button.hp-composer__send:not(:disabled) {
  background: #f7e0d7;
  border-color: #ebc2b5;
  color: #9e422c;
  box-shadow: inset 0 1px 0 #fff;
}
.hp-shell .hp-composer[data-action-phase="intent"] button.hp-composer__send:not(:disabled) {
  background: #b94025;
  border-color: #b94025;
  color: #fff;
  box-shadow: 0 5px 14px #b9402540;
  transform: translateY(-1px);
}
.hp-shell .hp-composer button.hp-composer__action {
  width: 42px;
  min-width: 42px;
  height: 42px;
  border-radius: 13px;
  display: grid;
  place-items: center;
}
.hp-composer__action svg {
  width: 19px;
  height: 19px;
  stroke-width: 1.9;
  pointer-events: none;
}
.hp-composer button.hp-composer__cancel {
  background: #eef3f7 !important;
  color: #b42318 !important;
  border-color: #d9e2e9 !important;
}
.hp-composer[data-action-phase="submitting"]:after,
.hp-composer[data-action-phase="uncertain"]:after {
  opacity: 0;
}
.hp-composer[data-action-phase="uncertain"] {
  border-color: #dabf8f;
}
.hp-action-relay {
  pointer-events: none !important;
  z-index: 90;
}
.hp-vitality[data-handoff] .hv-rotor {
  animation: none !important;
}
/* Smaller devices: real controls remain reachable, no false mobile navigation. */
@media (max-width: 959px) {
  .hp-shell .hp-composer {
    border-radius: 15px;
  }
}
@media (max-width: 599px) {
  .hp-shell .hp-composer {
    margin-bottom: 10px;
    padding: 10px;
  }
  .hp-execution-block:not(:has(.hp-runstrip)) > .hp-run-detail {
    grid-template-columns: minmax(0, 1fr) 28px !important;
    gap: 8px 9px !important;
    padding: 12px !important;
  }
  .hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-kind,
  .hp-execution-block:not(:has(.hp-runstrip)) .hp-run-reference-copy {
    grid-column: 1 !important;
  }
  .hp-run-card-status {
    grid-column: 1 !important;
    grid-row: 3 !important;
    justify-self: start;
  }
  .hp-execution-block:not(:has(.hp-runstrip)) .hp-run-card-meta {
    grid-column: 1 / span 2 !important;
    grid-row: 4 !important;
  }
  .hp-execution-block:not(:has(.hp-runstrip)) .hp-run-detail > svg {
    grid-column: 2 !important;
    grid-row: 1 / span 3 !important;
  }
  .hp-inspector .hp-surface-header {
    min-height: 70px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .hp-run-card-status[data-status="running"] .hp-run-card-dot {
    animation: none;
  }
  .hp-shell .hp-conv,
  .hp-rail nav button,
  .hp-shell .hp-composer,
  .hp-execution-block:not(:has(.hp-runstrip)) > .hp-run-detail {
    transition: none !important;
    transform: none !important;
  }
}

/* R4.2.6 · 接纳线缝 / 收紧的执行详情标题，R4.2.5 仅在本 EDITABLE 区更新。
   文字本身是主角；框的 11px 横向、7px 纵向间距由测量补丁实时计算。
   给左侧 11px 安全区，避免收束高光在 Inspector 面板边缘裁切。 */
.hp-run-identity.hp-run-reception {
  position: relative;
  display: flex;
  align-items: center;
  overflow: visible;
  min-height: 38px;
  padding: 6px 0 13px var(--r426-receiver-inset, 11px) !important;
  margin: 0;
  isolation: isolate;
}
.hp-run-identity .hp-inspector-receiver {
  position: relative;
  display: inline-block;
  width: max-content;
  max-width: 100%;
  margin: 0 !important;
  padding: 0 !important;
  min-height: 0;
  border: 0 !important;
  border-radius: 0 !important;
  background: none !important;
  box-shadow: none !important;
  color: #344858 !important;
  font-size: 16px !important;
  font-weight: 690 !important;
  letter-spacing: -0.018em !important;
  line-height: 1.52 !important;
  z-index: 2;
  isolation: isolate;
}
.hp-run-identity .hp-inspector-receiver::before,
.hp-run-identity .hp-inspector-receiver::after {
  content: none !important;
}
.hp-title-capture {
  position: absolute;
  z-index: 1;
  pointer-events: none;
  overflow: visible;
  opacity: 0;
  transform: none;
  filter: drop-shadow(0 1px 3px rgba(126, 150, 164, 0.12));
  transition: opacity 165ms ease;
}
.hp-title-capture[data-active="true"] {
  opacity: 1;
  transform: none;
}
.hp-title-capture .capture-frame {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.92;
}
.hp-title-capture .capture-sheen {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0.74;
}
.hp-title-capture .capture-shadow {
  fill: none;
  stroke: #dbe6eb;
  stroke-opacity: 0.26;
  stroke-width: 0.72;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.hp-title-capture .capture-node {
  opacity: 0.96;
  filter: drop-shadow(0 0 3px rgba(224, 161, 139, 0.3));
}
@media (prefers-reduced-motion: reduce) {
  .hp-title-capture {
    transition: none;
  }
}

/* R4.2.6 · One visual title only.
   Surface h2 remains the accessible dialog label and the reception h3 remains
   the genuine production filament target. When it is revealed, hide only the
   duplicate painted heading; keep the close/expand controls fully functional. */
.hp-inspector--run .hp-surface-header {
  min-height: 40px !important;
  padding: 7px 14px 5px !important;
  border-bottom: 0 !important;
}
.hp-inspector--run:has(.hp-run-identity .hp-inspector-receiver[data-revealed="true"])
  .hp-surface-header
  h2 {
  opacity: 0 !important;
  pointer-events: none;
}
.hp-inspector--run .hp-run-reception {
  margin-top: -2px;
}

/* Root title focus is still visible on keyboard navigation, but not a hard rectangle. */
#canvas-title:focus {
  outline: none;
}
#canvas-title:focus-visible .hp-title-trigger {
  outline: 2px solid #b9745f;
  outline-offset: 3px;
  border-radius: 7px;
}

/* R4.2.3 · Warm → Gradient → Silver Filament. Preserve true path length, arrival gating & close semantics.
   Source/TARGET positions and cubic path remain production-controlled. */
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-shell {
  stroke: #9eb6c5 !important;
  stroke-width: var(--hp-r422-mist, 6px) !important;
  stroke-opacity: 0.22 !important;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-core {
  stroke-width: var(--hp-r422-core, 1.7px) !important;
  stroke-dasharray: none !important;
  stroke-dashoffset: 0 !important;
  stroke-linecap: round;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-echo {
  stroke: #f8fcff !important;
  stroke-opacity: 0.88 !important;
  stroke-width: var(--hp-r422-highlight, 0.65px) !important;
  /* A porcelain light ridge, not a second thread. */
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-head {
  r: var(--hp-r422-head, 4.6px) !important;
  stroke: none !important;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-spark {
  stroke: none !important;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"]
  .hp-filament-spark[data-r422-muted="true"] {
  display: none !important;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"]
  .hp-filament-spark[data-r422-trace="true"] {
  r: 2.6px !important;
  filter: none !important;
}

/* R4.2.4 · Living Filament: one measured filament, one local travelling glint.
   A masked light ridge; no second full line, no new particles, no geometric displacement. */
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-living-glint {
  stroke-width: var(--hp-r424-glint-width, 2.45px);
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  filter: none;
  pointer-events: none;
  opacity: 0;
}
.hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-head {
  transition: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .hp-inspector-relay[data-r422-material="ember-gradient-silver"] .hp-filament-living-glint {
    display: none !important;
  }
}

/* The relay now carries a small origin ember, transitions through porcelain haze, and lands fully silver at Inspector. */
.hp-inspector-accept:before {
  background:
    radial-gradient(95px 32px at 24px 50%, rgba(228, 163, 138, 0.11), transparent 58%),
    linear-gradient(
      90deg,
      rgba(222, 154, 124, 0.18),
      rgba(225, 209, 205, 0.68) 32%,
      rgba(245, 248, 250, 0.92) 48%,
      rgba(177, 196, 208, 0.18) 76%,
      transparent
    ) !important;
}
.hp-inspector-accept:after {
  opacity: 0.63;
}
.hp-inspector-title-arrival {
  text-shadow: 0 0 6px rgba(223, 238, 246, 0.15);
}
@media (prefers-reduced-motion: reduce) {
  .hp-inspector-relay[data-r422-material="ember-gradient-silver"] {
    display: none !important;
  }
}

